<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { api } from '../api'
const route=useRoute(),router=useRouter(),id=computed(()=>route.params.id),points=ref([]),historyVersions=ref([]),selectedHistoryVersion=ref(''),error=ref(''),message=ref(''),file=ref(null)
const blankToken='{{blank}}'
const form=reactive({knowledgePointId:'',type:'CHOICE',origin:'MANUAL',maxScore:2,stem:'',options:[{key:'A',text:''},{key:'B',text:''},{key:'C',text:''}],correctOption:'A',fillAnswers:'',referenceAnswer:'',rubric:[{criterion:'',score:1}],explanation:'',sourceRef:'',version:null,status:'ACTIVE',suspensionReason:'',assets:[]})
const typeNames={CHOICE:'单选题',FILL:'填空题',SHORT_ANSWER:'简答 / 问答题',ALGORITHM:'算法设计题'}
const selectedHistory=computed(()=>historyVersions.value.find(item=>item.version===Number(selectedHistoryVersion.value)))
function addOption(){form.options.push({key:String.fromCharCode(65+form.options.length),text:''})}function addRubric(){form.rubric.push({criterion:'',score:1})}
function request(){let content={stem:form.stem},answer,rubric=null;if(form.type==='CHOICE'){content.options=form.options;answer={correctOption:form.correctOption}}else if(form.type==='FILL'){answer={blanks:form.fillAnswers.split('\n').map(line=>({accepted:line.split('|').map(x=>x.trim()).filter(Boolean)}))}}else{answer={referenceAnswer:form.referenceAnswer};rubric={items:form.rubric}}
 return {knowledgePointId:form.knowledgePointId,type:form.type,maxScore:form.maxScore,content,answer,rubric,explanation:form.explanation,sourceRef:form.sourceRef,expectedVersion:form.version}}
async function loadHistory(){if(!id.value)return;historyVersions.value=await api(`/api/admin/questions/${id.value}/versions`);if(!historyVersions.value.some(item=>item.version===Number(selectedHistoryVersion.value)))selectedHistoryVersion.value=''}
async function load(){try{points.value=await api('/api/admin/knowledge-points');if(!id.value){form.knowledgePointId=points.value.find(p=>p.enabled)?.id||'';return}const q=await api(`/api/admin/questions/${id.value}`);Object.assign(form,{knowledgePointId:q.knowledgePointId,type:q.type,origin:q.origin,maxScore:q.maxScore,stem:q.content.stem,explanation:q.explanation||'',sourceRef:q.sourceRef||'',version:q.version,status:q.status,suspensionReason:q.suspensionReason||'',assets:q.assets});if(q.type==='CHOICE'){form.options=q.content.options;form.correctOption=q.answer.correctOption}else if(q.type==='FILL')form.fillAnswers=q.answer.blanks.map(b=>b.accepted.join(' | ')).join('\n');else{form.referenceAnswer=q.answer.referenceAnswer;form.rubric=q.rubric.items}await loadHistory()}catch(e){error.value=e.message}}
async function save(){error.value='';message.value='';try{const previous=form.version;const q=id.value?await api(`/api/admin/questions/${id.value}`,{method:'PUT',body:request()}):await api('/api/admin/questions',{method:'POST',body:request()});message.value=id.value?(q.version===previous?'内容无变化，未新增版本':`已保存为版本 ${q.version}`):`已创建 ${q.questionNo}`;form.version=q.version;form.assets=q.assets||[];if(!id.value)router.replace(`/admin/questions/${q.id}`);else await loadHistory()}catch(e){error.value=e.message}}
async function changeStatus(){try{const path=form.status==='ACTIVE'?'suspend':'restore';const reason=form.status==='ACTIVE'?prompt('填写下架原因（必填）'):null;if(form.status==='ACTIVE'&&!reason)return;const q=await api(`/api/admin/questions/${id.value}/${path}`,{method:'POST',body:{reason,expectedVersion:form.version}});form.status=q.status;form.suspensionReason=q.suspensionReason||''}catch(e){error.value=e.message}}
async function upload(){if(!file.value)return;const data=new FormData();data.append('file',file.value);try{const asset=await api(`/api/admin/questions/${id.value}/assets`,{method:'POST',body:data});form.assets=[...form.assets,asset].sort((a,b)=>a.position-b.position);file.value=null;await loadHistory()}catch(e){error.value=e.message}}
async function deleteHistoryAsset(asset){if(!selectedHistory.value||!confirm(`确认删除版本 ${selectedHistory.value.version} 的这张历史题图？删除后文件不可恢复。`))return;try{await api(`/api/admin/question-assets/${asset.id}`,{method:'DELETE'});selectedHistory.value.assets=selectedHistory.value.assets.filter(item=>item.id!==asset.id);message.value=`已删除版本 ${selectedHistory.value.version} 的历史题图`}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section><div class="page-head"><div><h2>{{id?'编辑题目':'录入题目'}}</h2><p class="muted">每次实质修改生成不可变新版本；切换题型会启用对应答案控件。</p></div><div v-if="id" class="actions"><span :class="['badge',{active:form.status==='ACTIVE'}]">{{form.status==='ACTIVE'?'可用':'已下架'}}</span><button class="danger" @click="changeStatus">{{form.status==='ACTIVE'?'下架':'恢复'}}</button></div></div><form class="card grid" @submit.prevent="save"><div class="grid two"><label class="field">主知识点<select v-model="form.knowledgePointId" required><option v-for="p in points" :key="p.id" :value="p.id" :disabled="!p.enabled">{{p.code}} · {{p.name}}{{p.enabled?'':'（停用）'}}</option></select></label><label class="field">题型<select v-model="form.type"><option v-for="(label,key) in typeNames" :key="key" :value="key">{{label}}</option></select></label><label class="field">来源<span class="readonly-source">{{id&&form.origin==='AI_GENERATED'?'AI 生成（只读）':'人工录入（服务端固定）'}}</span></label><label class="field">满分<input v-model.number="form.maxScore" type="number" min="0.01" step="0.01" required></label></div><label class="field">题干<textarea v-model="form.stem" required :placeholder="form.type==='FILL'?`用 ${blankToken} 标记每个空格`:'输入完整题干'"></textarea></label><section v-if="form.type==='CHOICE'" class="answer-box"><header><h3>单选项</h3><button type="button" class="secondary" @click="addOption">增加选项</button></header><div v-for="(option,index) in form.options" :key="index" class="option"><input v-model="form.correctOption" type="radio" :value="option.key" :aria-label="`选 ${option.key} 为正确答案`"><input v-model="option.key" class="key" required maxlength="8"><input v-model="option.text" required :placeholder="`选项 ${option.key}`"></div></section><section v-else-if="form.type==='FILL'" class="answer-box"><h3>等价答案集合</h3><p class="muted">每个 <span class="code" v-text="blankToken"></span> 对应一行；同一空的等价答案用竖线分隔。</p><textarea v-model="form.fillAnswers" required placeholder="栈 | stack&#10;队列 | queue"></textarea></section><section v-else class="answer-box grid"><label class="field">参考答案<textarea v-model="form.referenceAnswer" required></textarea></label><header><h3>评分要点</h3><button type="button" class="secondary" @click="addRubric">增加要点</button></header><div v-for="(item,index) in form.rubric" :key="index" class="rubric"><input v-model="item.criterion" required placeholder="评分标准"><input v-model.number="item.score" type="number" min="0.01" step="0.01" required aria-label="分值"></div><p class="muted">当前合计 {{form.rubric.reduce((sum,x)=>sum+Number(x.score||0),0)}} / {{form.maxScore}} 分</p></section><div class="grid two"><label class="field">解析<textarea v-model="form.explanation"></textarea></label><label class="field">来源备注<textarea v-model="form.sourceRef"></textarea></label></div><div class="actions"><button class="primary">保存题目</button><RouterLink class="secondary" to="/admin/questions">返回列表</RouterLink></div></form><div v-if="id" class="card assets"><div><h3>当前版本题图</h3><p class="muted">仅 PNG/JPEG，实际解码后才会保存；每个版本最多 5 张、每张最多 5 MB。</p></div><div class="actions"><input type="file" accept="image/png,image/jpeg" @change="file=$event.target.files[0]"><button class="secondary" @click="upload">上传</button></div><div class="asset-list"><a v-for="a in form.assets" :key="a.id" :href="`/api/question-assets/${a.id}`" target="_blank">图 {{a.position+1}} · {{a.width}}×{{a.height}} · {{Math.ceil(a.sizeBytes/1024)}} KB</a></div></div><div v-if="id&&historyVersions.length" class="card history-assets"><div><h3>历史版本题图</h3><p class="muted">先选择历史版本；删除只影响该历史版本，确认后物理文件不可恢复。</p></div><label class="field history-select">查看版本<select v-model="selectedHistoryVersion"><option value="">请选择</option><option v-for="item in historyVersions" :key="item.version" :value="item.version">版本 {{item.version}} · {{item.content.stem}}</option></select></label><div v-if="selectedHistory" class="history-view"><p class="history-stem"><span class="code">v{{selectedHistory.version}}</span> {{selectedHistory.content.stem}}</p><p v-if="!selectedHistory.assets.length" class="muted">该历史版本没有题图。</p><div v-for="a in selectedHistory.assets" :key="a.id" class="history-asset"><a :href="`/api/question-assets/${a.id}`" target="_blank">图 {{a.position+1}} · {{a.width}}×{{a.height}} · {{Math.ceil(a.sizeBytes/1024)}} KB</a><button class="danger" @click="deleteHistoryAsset(a)">删除历史题图</button></div></div></div><p class="success">{{message}}</p><p class="error">{{error}}</p></section></template>
<style scoped>.answer-box{border:1px solid #dce2ea;border-left:4px solid #286a64;border-radius:9px;padding:16px;background:#f9fafb}.answer-box header{display:flex;justify-content:space-between;align-items:center}.answer-box h3{margin:0 0 10px}.readonly-source{display:block;padding:9px 10px;border:1px solid #dce2ea;border-radius:7px;background:#f4f6f8;color:#526071}.option,.rubric{display:grid;grid-template-columns:28px 55px 1fr;gap:8px;margin-top:8px}.rubric{grid-template-columns:1fr 110px}.option input,.rubric input,.answer-box textarea{border:1px solid #cfd6e1;border-radius:6px;padding:9px;width:100%}.assets,.history-assets{margin-top:16px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.assets h3,.history-assets h3{margin:0}.asset-list{flex-basis:100%;display:flex;gap:10px;flex-wrap:wrap}.asset-list a,.history-asset a{color:#286a64}.history-select{min-width:280px}.history-view{flex-basis:100%;border-top:1px solid #e3e7ed;padding-top:14px}.history-stem{color:#344054}.history-asset{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:10px 0;border-top:1px solid #eef0f3}</style>
